import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"Database Organization","description":"","frontmatter":{"title":"Database Organization","lang":"en-US"},"headers":[],"relativePath":"software/db_organization.md","filePath":"software/db_organization.md"}`),a={name:`software/db_organization.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="database-organization" tabindex="-1">Database Organization <a class="header-anchor" href="#database-organization" aria-label="Permalink to “Database Organization”">​</a></h1><p>The following sections describe all databases on the BRAIN CoGS host (datajoint00.pni.princeton.edu). The databases fall into these categories:</p><ol><li><a href="#lab-subject-schedule-dbs">Lab, subject &amp; schedule DBs</a></li><li><a href="#behavior-dbs">Behavior DBs</a></li><li><a href="#ephys-imaging-dbs">Ephys &amp; imaging DBs</a></li></ol><h2 id="lab-subject-schedule-dbs" tabindex="-1">Lab, Subject &amp; Schedule DBs <a class="header-anchor" href="#lab-subject-schedule-dbs" aria-label="Permalink to “Lab, Subject &amp; Schedule DBs”">​</a></h2><h3 id="_1-u19-lab" tabindex="-1"><strong>1. u19_lab</strong> <a class="header-anchor" href="#_1-u19-lab" aria-label="Permalink to “1. u19_lab”">​</a></h3><ul><li>Stores general information that applies across all BRAIN CoGS projects, including information about researchers.</li></ul><h4 id="main-tables" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>User</strong> Stores general information for all researchers and technicians in BRAIN CoGS. You must be registered in this table to have subjects added under your name (see <a href="/software/db_access.html#add-researcher-to-user-table">here</a> for more information). Important fields include user_id (NETID), active_gui_user, and slack_webhook URLs for users (for notifications). See <a href="/software/alert_system.html#set-up-custom-slack-alerts">Slack alerts</a> for more information.</li><li><strong>Location</strong> All systems associated with rigs, recordings, and technician use. Every behavior session is associated with one of the systems recorded here, and each recording (ephys/imaging) is associated with a system recorded here.</li><li><strong>Path</strong> Paths for the cup drives in BRAIN CoGS. Paths are divided by OS and by local or network system type.</li><li><strong>AcquisitionType</strong> All possible acquisition modalities in BRAIN CoGS (each location in Path is associated with one modality as well). Modalities include behavior, electrophysiology, 2photon, mesoscope, etc.</li><li><strong>DjCustomVariables</strong> Configuration variables for DataJoint, mainly paths for special directories. This table is used in the background when DB access is configured for a system (see the <a href="/software/db_access.html#db-access-for-matlab-repository">DB access section</a>).</li><li><strong>DjStores</strong> External storage path locations on the network drives (cup) for several DataJoint tables. This table is used in the background when DB access is configured for a system (see the <a href="/software/db_access.html#db-access-for-matlab-repository">DB access section</a>).</li><li><strong>InsertionDevice</strong> Device types for insertion in subjects (from ephys electrodes to optogenetic cannulae). Paired with the u19_action.SurgeryLocation table.</li><li><strong>SlackWebhooks</strong> Slack webhook URLs for general notifications. See <a href="/software/alert_system.html#set-up-custom-slack-alerts">Slack alerts</a> for more information.</li></ul><h3 id="_2-u19-subject" tabindex="-1"><strong>2. u19_subject</strong> <a class="header-anchor" href="#_2-u19-subject" aria-label="Permalink to “2. u19_subject”">​</a></h3><ul><li>Stores all general information for subjects (mice) registered for experiments.</li></ul><h4 id="main-tables-1" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-1" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>Subject</strong> Stores general information for all subjects in BRAIN CoGS. Being registered in this table is a requirement to train and run behavior sessions.</li><li><strong>LickometerMotorPosition</strong> Stores ml, ap, and dv motor coordinates for a subject in a rig with a positioning motor installed. See the <a href="/software/virmen_guide.html#set-up-training">motor positioning setup</a> for more information.</li><li><strong>CagingStatus</strong> Subject-cage relationship storage.</li><li><strong>HealthStatus</strong> Daily health assessment for a subject. Fields include normal_behavior, posture_grooming, technician_comments, etc.</li><li><strong>Allele</strong> All subjects&#39; genotypes in BRAIN CoGS.</li><li><strong>Cage</strong> Cage list for subjects.</li></ul><h3 id="_3-u19-scheduler" tabindex="-1"><strong>3. u19_scheduler</strong> <a class="header-anchor" href="#_3-u19-scheduler" aria-label="Permalink to “3. u19_scheduler”">​</a></h3><ul><li>Stores everything related to scheduling future sessions for subjects in the <a href="/software/virmen_developer.html#new-training-gui"> &quot;NewTrainingGUI&quot; model </a>.</li><li>It includes current rig IOs, training profiles for all experiments, and the schedule calendar for future sessions.</li></ul><h4 id="main-tables-2" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-2" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>Schedule</strong> Records which subjects are scheduled to train, on which date, on which rig, and which training profile they are assigned.</li><li><strong>TrainingProfile</strong> All variables for a given experiment (e.g. experiment world, protocol, rewardFactor). See the <a href="/software/virmen_developer.html#testvrrig-2-rig-tester">Rig Tester</a> documentation for more information.</li><li><strong>InputOutputRig</strong> All IO &quot;types&quot; defined for every rig (e.g. Reward, LeftAirPuff, Arduino). See the <a href="/software/virmen_developer.html#testvrrig-2-rig-tester">Rig Tester</a> documentation for more information.</li><li><strong>InputOutputRigParameters</strong> All RigParameters.m parameters needed for a given IO.</li><li><strong>InputOutputProfile</strong> Defines which IOs are needed for a specific rig and/or task.</li></ul><h2 id="behavior-dbs" tabindex="-1">Behavior DBs <a class="header-anchor" href="#behavior-dbs" aria-label="Permalink to “Behavior DBs”">​</a></h2><h3 id="_1-u19-acquisition" tabindex="-1"><strong>1. u19_acquisition:</strong> <a class="header-anchor" href="#_1-u19-acquisition" aria-label="Permalink to “1. u19_acquisition:”">​</a></h3><ul><li>Stores all reference and general information for behavior sessions. Other tables in this database also store references to the blocks, trials, manipulations, and subtasks of a behavior session.</li></ul><h4 id="main-tables-3" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-3" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>SessionStarted</strong> Reference to all sessions started with the training GUI. The path to the behavior file is located here.</li><li><strong>Session</strong> Basic information (performance, experiment code used, etc.) for a behavior session. The record is written after training is finished.</li><li><strong>SessionBlock</strong> Basic reference to all blocks from all behavior sessions.</li><li><strong>SessionBlockTrial</strong> Basic reference to all trials from all behavior sessions.</li><li><strong>SessionManipulation</strong> Reference to which manipulation (if any) was performed for a behavior session. See the <a href="/software/manipulation_pipeline.html">manipulation pipeline section</a> for more information.</li><li><strong>SessionSubtask</strong> Reference to which subtask (if any) was performed for a behavior session. See the <a href="/software/subtask_pipeline.html">subtask pipeline section</a> for more information.</li><li><strong>SessionVideo</strong> Reference to video acquisition, if performed during a behavior session. See the <a href="/software/pupillometry_guide.html">Pupillometry Pipeline Guide</a> for more information.</li></ul><h3 id="_2-u19-action" tabindex="-1"><strong>2. u19_action:</strong> <a class="header-anchor" href="#_2-u19-action" aria-label="Permalink to “2. u19_action:”">​</a></h3><ul><li>Stores daily, recurrent, and specific actions performed on subjects.</li></ul><h4 id="main-tables-4" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-4" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>Weighing</strong> Records the daily weight of subjects. Written by the weighingGUI used by technicians.</li><li><strong>WaterAdministration</strong> Records daily water administration to subjects. Earned water is written at the end of training. Supplement water is written by the weighingGUI used by technicians.</li><li><strong>Surgery</strong> Records of surgeries performed on subjects. Written by the <a href="/software/automation_pipeline.html">ephys/imaging automation pipeline</a>.</li><li><strong>SurgeryLocation</strong> Records device locations implanted in subjects during surgeries (e.g. Neuropixels probes). Written by the <a href="/software/automation_pipeline.html">ephys/imaging automation pipeline</a>.</li><li><strong>DailyPositionData</strong> For subjects with automatic motor positioning on a rig, stores daily ml, ap, and dv coordinates. If cameras are present on the rig, lateral and top reference images are also stored.</li></ul><h3 id="_3-u19-behavior" tabindex="-1"><strong>3. u19_behavior:</strong> <a class="header-anchor" href="#_3-u19-behavior" aria-label="Permalink to “3. u19_behavior:”">​</a></h3><ul><li>Stores detailed data for behavior sessions. Built to support Towers Task data, but stores data from all behavior sessions.</li></ul><h4 id="main-tables-5" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-5" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>TowersBlock</strong> Specific block data from behavior sessions (level, main_level, block_performance, etc.).</li><li><strong>TowersBlockTrial</strong> Specific trial data from behavior sessions (tower positions, trial_type, choice, position, velocity, etc.).</li><li><strong>SpatialTimeBlobs</strong> Efficient time, position, and velocity storage (per session, not per trial). See <a href="/software/db_analysis.html#get-full-trial-data-with-spatialtimeblobs">get_full_trial_data with SpatialTimeBlobs</a> to learn how to use it.</li><li><strong>Towers Session/Subject Psych</strong> Group of tables with psychometric curve parameters per session, block_type (main, guiding), subject, etc. View psychometric curves in the <a href="https://braincogs01.pni.princeton.edu/">BRAIN CoGS data viewer</a>.</li></ul><h3 id="_4-u19-behavior-subtask" tabindex="-1"><strong>4. u19_behavior_subtask:</strong> <a class="header-anchor" href="#_4-u19-behavior-subtask" aria-label="Permalink to “4. u19_behavior_subtask:”">​</a></h3><ul><li>Stores specific data for different subtask sessions. See the <a href="/software/subtask_pipeline.html">subtask pipeline section</a> for more information.</li></ul><h3 id="_5-u19-optogenetics" tabindex="-1"><strong>5. u19_optogenetics</strong> <a class="header-anchor" href="#_5-u19-optogenetics" aria-label="Permalink to “5. u19_optogenetics”">​</a></h3><ul><li>Optogenetic manipulation data. See the <a href="/software/manipulation_pipeline.html">manipulation pipeline section</a> for more information and examples.</li></ul><h4 id="main-tables-6" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-6" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>OptogeneticSession</strong> Reference to a behavior session that is also an optogenetic session. Stores which protocol and software parameter set were used for the session.</li><li><strong>OptogeneticSessionTrial</strong> Stores specific optogenetic data on a trial-by-trial basis.</li><li><strong>OptogeneticSoftwareParameters</strong> MATLAB structure with parameters to be used during the behavior session, specific to a subset of optogenetic sessions.</li><li><strong>OptogeneticProtocol</strong> Describes metadata associated with optogenetic sessions (e.g. laser wavelength, stimulation frequency, etc.).</li></ul><h3 id="_6-u19-thermal" tabindex="-1"><strong>6. u19_thermal</strong> <a class="header-anchor" href="#_6-u19-thermal" aria-label="Permalink to “6. u19_thermal”">​</a></h3><ul><li>Thermal manipulation data. See the <a href="/software/manipulation_pipeline.html">manipulation pipeline section</a> for more information and examples. Identical structure to the Optogenetic DB.</li></ul><h3 id="_7-u19-puffs" tabindex="-1"><strong>7. u19_puffs</strong> <a class="header-anchor" href="#_7-u19-puffs" aria-label="Permalink to “7. u19_puffs”">​</a></h3><ul><li>Air puff task session-specific data.</li></ul><h4 id="main-tables-7" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-7" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>PuffsSession</strong> Reference to a behavior session that is also a puff session.</li><li><strong>PuffsSessionTrial</strong> Stores specific puffs data on a trial-by-trial basis.</li></ul><h2 id="ephys-imaging-dbs" tabindex="-1">Ephys/Imaging DBs <a class="header-anchor" href="#ephys-imaging-dbs" aria-label="Permalink to “Ephys/Imaging DBs”">​</a></h2><h3 id="_1-u19-recording" tabindex="-1"><strong>1. u19_recording:</strong> <a class="header-anchor" href="#_1-u19-recording" aria-label="Permalink to “1. u19_recording:”">​</a></h3><ul><li>Stores references to all recordings (ephys and imaging) made at BRAIN CoGS. See the <a href="/software/automation_pipeline.html">automation pipeline section</a> for more information.</li></ul><h4 id="main-tables-8" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-8" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>Recording</strong> Reference to all recordings. Stores information such as location, status_recording, and recording directory on the network drives.</li><li><strong>RecordingBehaviorSessions</strong> Relationship between recordings and behavior sessions. <strong>(recording_id &lt;-&gt; session_key (subject, date, #)</strong></li><li><strong>RecordingRecordingSession</strong> Relationship between recordings and subject/date. Used when no behavior is attached to a recording.</li><li><strong>Modality</strong> List of all possible modalities supported by the automation pipeline.</li></ul><h3 id="_2-u19-recording-process" tabindex="-1"><strong>2. u19_recording_process:</strong> <a class="header-anchor" href="#_2-u19-recording-process" aria-label="Permalink to “2. u19_recording_process:”">​</a></h3><ul><li>Stores all references to processing jobs for ephys and imaging in the automation pipeline. Almost all information in this table is shown in the <a href="/software/automation_pipeline.html#monitor-jobs">automation pipeline GUI</a>.</li></ul><h4 id="main-tables-9" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-9" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>Processing</strong> Reference to all processing jobs. For ephys, it has a one-to-one relationship with recording probes. For imaging, it has a one-to-one relationship with the field of view. Stores <strong>status_processing, raw_path (recording_process_pre_path), processed_path (recording_process_post_path)</strong> for each of these &quot;fragments&quot; of a recording.</li><li><strong>ProcessingEphysParams</strong> Relationship between jobs and which ephys processing parameters were used for each job.</li><li><strong>ProcessingImagingParams</strong> Relationship between jobs and which imaging processing parameters were used for each job.</li><li><strong>LogStatus</strong> Stores all status changes for processing jobs, along with the corresponding messages and exceptions if applicable.</li></ul><h3 id="_3-u19-ephys-pipeline" tabindex="-1"><strong>3. u19_ephys_pipeline:</strong> <a class="header-anchor" href="#_3-u19-ephys-pipeline" aria-label="Permalink to “3. u19_ephys_pipeline:”">​</a></h3><ul><li>Basic reference to recordings and behavior synchronization data.</li></ul><h4 id="main-tables-10" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-10" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>EphysPipelineSession</strong> List of recording_ids that correspond to ephys recordings.</li><li><strong>BehaviorSync</strong> Synchronization data between the ephys recording and the behavior session. <strong>trial_index_nidq &amp; iteration_index_nidq</strong> are the trial and iteration # for each sample in the electrophysiology data.</li></ul><h3 id="_4-u19-pipeline-ephys-element" tabindex="-1"><strong>4. u19_pipeline_ephys_element:</strong> <a class="header-anchor" href="#_4-u19-pipeline-ephys-element" aria-label="Permalink to “4. u19_pipeline_ephys_element:”">​</a></h3><ul><li>DataJoint element array electrophysiology DB. The database schema is designed to store all data from an ephys recording and the subsequent Kilosort processing. More info: <a href="https://datajoint.com/docs/elements/element-array-ephys/0.2/">DataJoint Element Array Electrophysiology docs</a>. For BRAIN CoGS, the <strong>ephys_precluster</strong> schema was used.</li></ul><h4 id="main-tables-11" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-11" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>ClusteringParamSet</strong> Contains a list of parameter dictionaries/structures used for the sorting process.</li><li><strong>PreClusterparamSet</strong> Contains a list of parameter dictionaries/structures used for preprocessing steps.</li><li><strong>PreClusterparamSteps</strong> Contains lists of PreCluster param sets that form a sequence of preprocessing steps for recordings (e.g. CatGT).</li><li><strong>CuratedClusteringUnit</strong> Main data for all the units found in the sorting process (<strong>spike_times, cluster_quality_label</strong>, etc.).</li><li><strong>LFPElectrode</strong> LFP data for each of the electrodes in a recording.</li><li><strong>WaveformSetWaveform</strong> All waveforms from a unit captured by each electrode in a recording.</li><li><strong>ProbeInsertion</strong> Records which probe was used for the corresponding recording-insertion_number pair. Check <strong>5. u19_pipeline_probe_element</strong>.</li></ul><h3 id="_5-u19-pipeline-probe-element" tabindex="-1"><strong>5. u19_pipeline_probe_element:</strong> <a class="header-anchor" href="#_5-u19-pipeline-probe-element" aria-label="Permalink to “5. u19_pipeline_probe_element:”">​</a></h3><ul><li>DataJoint element array electrophysiology DB for probes. The database schema is designed to store the probes and electrode configurations used in recordings. More info: <a href="https://datajoint.com/docs/elements/element-array-ephys/0.2/">DataJoint Element Array Electrophysiology docs</a>. For BRAIN CoGS, the <strong>ephys_precluster</strong> schema was used.</li></ul><h4 id="main-tables-12" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-12" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>Probe</strong> Contains all physical probes used in recordings.</li><li><strong>ProbeTypeElectrode</strong> Contains coordinates, shank #, and id for each electrode in a probe.</li></ul><h3 id="_6-u19-imaging-pipeline" tabindex="-1"><strong>6. u19_imaging_pipeline:</strong> <a class="header-anchor" href="#_6-u19-imaging-pipeline" aria-label="Permalink to “6. u19_imaging_pipeline:”">​</a></h3><ul><li>Reference to all imaging recordings and the subsequent fields of view (FOV) identification and splitting for processing.</li></ul><h4 id="main-tables-13" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-13" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>ImagingPipelineSession</strong> List of recording_ids that correspond to imaging recordings.</li><li><strong>TiffSplit</strong> Identified fields of view for a single recording (typically 2photon = 1 FOV, mesoscope = 3 FOV). Each FOV is processed separately.</li><li><strong>AcquiredTiff</strong> TIFF file header metadata for each FOV.</li><li><strong>SyncImagingBehavior</strong> Synchronization data between the imaging recording and the behavior session. <strong>sync_behav_%%_by_im_frame</strong> = corresponding behavior block, trial, and iteration for each imaging frame. <strong>sync_im_frame_span_by_behav_%%</strong> = first and last imaging frame for each behavior block, trial, and iteration.</li></ul><h3 id="_7-u19-pipeline-imaging-element" tabindex="-1"><strong>7. u19_pipeline_imaging_element:</strong> <a class="header-anchor" href="#_7-u19-pipeline-imaging-element" aria-label="Permalink to “7. u19_pipeline_imaging_element:”">​</a></h3><ul><li>DataJoint element calcium imaging DB. The database schema is designed to store all data from an imaging recording and the subsequent segmentation process. More info: <a href="https://datajoint.com/docs/elements/element-calcium-imaging/0.5/">DataJoint Element Calcium Imaging docs</a>.</li></ul><h4 id="main-tables-14" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-14" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>ProcessingParamSet</strong> Contains a list of parameter dictionaries/structures used for the segmentation process.</li><li><strong>ActivityTrace</strong> Activity trace signals for all masks identified in the segmentation process.</li><li><strong>FluorescenceTrace</strong> Fluorescence trace signals for all masks identified in the segmentation process.</li><li><strong>MaskClassificationMaskType</strong> Mask types (soma, blob, doughnut, etc.) and confidence for each mask identified in the segmentation process.</li><li><strong>MotionCorrection(non)RigidMotionCorrection</strong> Motion correction details (shifts, outlier_frames, etc.) performed during processing.</li><li><strong>MotionCorrectionSummary</strong> Summary (average, correlation, max_proj) images for each field and channel after motion correction.</li></ul><h3 id="_8-u19-pipeline-scan-element" tabindex="-1"><strong>8. u19_pipeline_scan_element:</strong> <a class="header-anchor" href="#_8-u19-pipeline-scan-element" aria-label="Permalink to “8. u19_pipeline_scan_element:”">​</a></h3><ul><li>DataJoint element calcium imaging DB. The database schema is designed to store scan info and metadata from imaging files. More info: <a href="https://datajoint.com/docs/elements/element-calcium-imaging/0.5/">DataJoint Element Calcium Imaging docs</a>.</li></ul><h4 id="main-tables-15" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-15" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>ScanInfo</strong> Similar to <strong>u19_imaging_pipeline.AcquiredTiff</strong>. General data and metadata from scans.</li><li><strong>ScanInfoField</strong> Data specific to each of the fields of the scan.</li><li><strong>ScanInfoScanFile</strong> All files that are part of a scan.</li></ul><h3 id="_9-u19-pupillometry" tabindex="-1"><strong>9. u19_pupillometry:</strong> <a class="header-anchor" href="#_9-u19-pupillometry" aria-label="Permalink to “9. u19_pupillometry:”">​</a></h3><ul><li>Stores everything related to pupillometry recordings, from references to behavior sessions to final results. See the <a href="/software/pupillometry_guide.html">Pupillometry Pipeline Guide</a> for more information.</li></ul><h4 id="main-tables-16" tabindex="-1">Main tables <a class="header-anchor" href="#main-tables-16" aria-label="Permalink to “Main tables”">​</a></h4><ul><li><strong>PupillometrySession</strong> Reference to a behavior session that had pupillometry acquisition.</li><li><strong>PupillometryModels</strong> Training models ready to use for processing pupillometry data.</li><li><strong>PupillometrySyncBehavior</strong> Time correspondence between each trial-iteration in the behavior file and each video frame.</li><li><strong>PupillometrySessionModel</strong> Reference to which model was used to process a behavior session (more than one model can be used to process data from a session).</li><li><strong>PupillometrySessionModelData</strong> Status of pupillometry processing and final result storage.</li></ul>`,78)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};